/**
 * Google Sheets Node - Version 4.4
 * Discriminator: resource=sheet, operation=delete
 */


interface Credentials {
  googleApi: CredentialReference;
  googleSheetsOAuth2Api: CredentialReference;
}

/** Delete columns or rows from a sheet */
export type GoogleSheetsV44SheetDeleteParams = {
  resource: 'sheet';
  operation: 'delete';
  authentication?: 'serviceAccount' | 'oAuth2' | Expression<string>;
/**
 * Document
 * @builderHint Default to mode: 'list', which is easiest for users to set up: it gives them the From-list picker at setup. Use mode: 'id' only when the user supplied a concrete spreadsheet ID; otherwise use mode: 'list' with an empty value and a cachedResultName placeholder (e.g. the sheet name from the prompt). Never invent or fabricate a spreadsheet ID. Resource locator value must be `{ __rl: true, mode, value }`, not a plain string or `expr()` wrapper.
 * @searchListMethod spreadSheetsSearch
 * @default {"mode":"list","value":""}
 */
    documentId?: { __rl: true; mode: 'list' | 'url' | 'id'; value: string; cachedResultName?: string };
/**
 * Sheet
 * @builderHint Default to mode: 'list' when you have a real numeric sheet ID (gid) from explored resources. If you only know the sheet by its name, use mode: 'name' with that name — a title placed in list or id mode cannot resolve. Resource locator value must be `{ __rl: true, mode, value }` — never a plain string or `expr()` wrapper.
 * @searchListMethod sheetsSearch
 * @default {"mode":"list","value":""}
 */
    sheetName?: { __rl: true; mode: 'list' | 'url' | 'id' | 'name'; value: string; cachedResultName?: string };
/**
 * What to delete
 * @displayOptions.hide { sheetName: [""] }
 * @default rows
 */
    toDelete?: 'rows' | 'columns' | Expression<string>;
/**
 * The row number to delete from, The first row is 2
 * @displayOptions.show { toDelete: ["rows"] }
 * @displayOptions.hide { sheetName: [""] }
 * @default 2
 */
    startIndex?: number | Expression<number>;
/**
 * Number of Rows to Delete
 * @displayOptions.show { toDelete: ["rows"] }
 * @displayOptions.hide { sheetName: [""] }
 * @default 1
 */
    numberToDelete?: number | Expression<number>;
};

export type GoogleSheetsV44SheetDeleteNode = {
  type: 'n8n-nodes-base.googleSheets';
  version: 4.4;
  config: NodeConfig<GoogleSheetsV44SheetDeleteParams> & { credentials?: Credentials };
};